{
  "implementation": "def solve(case):
    import copy
    payload = case['payload']
    segments = payload['segments']
    budget = payload['budget']

    # Extract fields
    names = [s['name'] for s in segments]
    importances = [s['importance'] for s in segments]
    minimums = [s['minimum'] for s in segments]
    capacities = [s['capacity'] for s in segments]

    sum_min = sum(minimums)
    sum_cap = sum(capacities)

    if budget < sum_min:
        return {'error': 'Budget less than sum of minimum quotas', 'budget': budget, 'sum_min': sum_min}
    if budget > sum_cap:
        return {'error': 'Budget exceeds total capacity', 'budget': budget, 'sum_cap': sum_cap}

    # Initialize allocations to minimums
    allocations = minimums[:]
    remaining = budget - sum_min

    # While there is budget left, allocate one token to the best segment
    while remaining > 0:
        best_idx = -1
        best_ratio = -1.0
        for i in range(len(segments)):
            if allocations[i] < capacities[i]:
                next_pos = allocations[i] + 1
                ratio = importances[i] / float(next_pos)
                if ratio > best_ratio:
                    best_ratio = ratio
                    best_idx = i
                # tie-breaking: if equal, keep earlier (since we iterate in order, and only update on strictly greater)
        if best_idx == -1:
            # Should not happen because budget <= total capacity, but guard
            break
        allocations[best_idx] += 1
        remaining -= 1

    # Build output
    allocation_map = {names[i]: allocations[i] for i in range(len(names))}
    return {
        'allocations': allocation_map,
        'name_mapping': names,
        'total_allocated': budget
    }"
}
